import sys, json, time, platform, statistics as stats
from pathlib import Path

START = time.time()
sys.path.append('storage/shared')

# Seeding utilities (package or shim)
seed_tools_ok = True
try:
    from utilities.seed_tools import set_seed, make_rng, seed_from_str, mix_seed
except Exception:
    seed_tools_ok = False
    try:
        from seed_tools import set_seed, make_rng, seed_from_str, mix_seed
    except Exception:
        import random as _r, hashlib as _h
        def _u32(x): return int(x) & 0xFFFFFFFF
        def set_seed(s): _r.seed(_u32(s)); return _u32(s)
        def make_rng(s): set_seed(s); return None, _r.Random(_u32(s))
        def seed_from_str(s): return int(_h.sha256(s.encode()).hexdigest()[:8], 16)
        def mix_seed(a,b): return (_u32(a) ^ (_u32(b) + 0x9E3779B9)) & 0xFFFFFFFF

from coord.adaptive_lossy_ring import run_adaptive_lossy

base_seed = seed_from_str("Axiom-adaptive-lossy-ring-v0.1")
set_seed(base_seed)
_, _ = make_rng(base_seed)

cfg = {
    "N": 24,
    "max_steps": 400,
    "reliability": 0.8,
    "p0": 0.4,
    "replicates": 10,
    "targets": {
        "target_delta": 0.10,
        "target_dps": 12,   # deliveries per step goal (approx half of N for bidir)
        "p_min": 0.1,
        "p_max": 1.0,
        "k_cov": 0.8,
        "k_dps": 0.05,
    },
    "sampler_cfg": {
        "initial_rate": 0.4,
        "adjustment_factor": 1.5
    },
    "modes": ["uni", "bidir"]
}

runs = {"uni": [], "bidir": []}
for r in range(cfg["replicates"]):
    for mode in cfg["modes"]:
        run_seed = mix_seed(base_seed, (r + 1) * (2 if mode == "bidir" else 1))
        res = run_adaptive_lossy(
            N=cfg["N"],
            max_steps=cfg["max_steps"],
            base_seed=run_seed,
            reliability=cfg["reliability"],
            bidirectional=(mode == "bidir"),
            p0=cfg["p0"],
            sampler_cfg=cfg["sampler_cfg"],
            targets=cfg["targets"],
            track_history=True,
        )
        runs[mode].append(res)

def agg_for(mode):
    items = runs[mode]
    metrics = [x["metrics"] for x in items]
    def vals(key):
        v = [m.get(key) for m in metrics if m.get(key) is not None]
        return v
    # deliveries per step
    dps = [x["deliveries"] / x["steps"] for x in items if x["steps"] > 0]
    controllers = list({x.get("controller", {}).get("type", "?") for x in items})
    agg = {}
    for key in ["coverage", "time_to_full", "throughput_msgs_per_step"]:
        v = vals(key)
        if v:
            agg[key] = {
                "count": len(v),
                "mean": float(stats.fmean(v)),
                "min": float(min(v)),
                "max": float(max(v)),
            }
        else:
            agg[key] = {"count": 0}
    agg["deliveries_per_step_mean"] = float(stats.fmean(dps)) if dps else None
    return {"aggregate": agg, "controller_types": controllers}

out_dir = Path("storage/shared/coord/results")
out_dir.mkdir(parents=True, exist_ok=True)
out_path = out_dir / "axiom_adaptive_lossy_v01.json"

report = {
    "env": {
        "python": platform.python_version(),
        "implementation": platform.python_implementation(),
        "platform": platform.platform(),
        "seed_tools_imported": seed_tools_ok,
    },
    "config": cfg,
    "uni": {
        "runs": runs["uni"],
        "summary": agg_for("uni"),
    },
    "bidir": {
        "runs": runs["bidir"],
        "summary": agg_for("bidir"),
    },
}

with open(out_path, "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2, sort_keys=True)

END = time.time()
print("=== Adaptive Lossy Links Ring v0.1 ===")
print(json.dumps({
    "artifact": str(out_path),
    "uni_time_to_full_mean": report["uni"]["summary"]["aggregate"]["time_to_full"].get("mean"),
    "bidir_time_to_full_mean": report["bidir"]["summary"]["aggregate"]["time_to_full"].get("mean"),
    "uni_deliveries_per_step_mean": report["uni"]["summary"]["aggregate"]["deliveries_per_step_mean"],
    "bidir_deliveries_per_step_mean": report["bidir"]["summary"]["aggregate"]["deliveries_per_step_mean"],
    "controller_types": {
        "uni": report["uni"]["summary"]["controller_types"],
        "bidir": report["bidir"]["summary"]["controller_types"],
    },
    "timing_sec": round(END - START, 6),
}, indent=2))
print("Adaptive lossy control complete.")
